//! #12880: a script range maps only to generated bytes that copy it.
#![expect(clippy::string_slice, reason = "tests assert by panicking")]
use super::super::document::project_type_aware;
use super::{Plan, generated_range};

/// Each macro, between a statement before it and a statement after it.
const MACROS: &[&str] = &[
    "const model = defineModel<boolean>({ default: false });",
    "const open = defineModel<boolean>(\"open\", { required: true });",
    "const props = defineProps<{ title: string; count?: number }>();",
    "const props = defineProps({ title: { type: String, required: true } });",
    "const props = withDefaults(defineProps<{ title?: string }>(), { title: \"x\" });",
    "const { title = \"x\", count = 0 } = defineProps<{ title?: string; count?: number }>();",
    "const emit = defineEmits<{ change: [value: number] }>();",
    "const slots = defineSlots<{ default(props: { item: string }): unknown }>();",
    "defineExpose({ focus: () => {} });",
    "defineOptions({ name: \"MacroShapes\", inheritAttrs: false });",
];

const BEFORE: &str = "const before = `${numbers}`;";
const AFTER: &str = "const after = `${numbers}`;";

#[test]
fn every_macro_and_its_neighbours_map_to_their_setup_copy() {
    for statement in MACROS {
        let source = vize_l0::cstr!(
            "<script setup lang=\"ts\">\nconst numbers = [1, 2, 3];\n{BEFORE}\n{statement}\n{AFTER}\n</script>\n"
        );
        let descriptor =
            vize_atelier_sfc::parse_sfc(&source, vize_atelier_sfc::SfcParseOptions::default())
                .expect("sfc");
        let script = descriptor.script_setup.as_ref().expect("script setup");
        let document = project_type_aware(
            &descriptor,
            script.content.as_ref(),
            None,
            script.loc.start as u32,
            0,
            "MacroShapes.vue",
        );
        let setup = document
            .content
            .find("// User setup code")
            .expect("setup body");
        let plan = Plan::from_descriptor(&descriptor, document.mapping);
        let script = plan.scripts.last().expect("setup script");
        let call = statement
            .find("define")
            .or_else(|| statement.find("withDefaults"))
            .expect("macro call");
        let call_text = statement[call..].trim_end_matches(';');
        let callee = &call_text[..call_text.find(['<', '(']).expect("callee end")];
        for authored in [BEFORE, "`${numbers}`", *statement, call_text, callee, AFTER] {
            let occurrences = script
                .content
                .match_indices(authored)
                .map(|(start, _)| start)
                .collect::<Vec<_>>();
            assert!(!occurrences.is_empty(), "{authored} in {statement}");
            for start in occurrences {
                let end = start + authored.len();
                let (generated_start, generated_end) = generated_range(
                    &plan.mapping,
                    &document.content,
                    script,
                    start as u32,
                    end as u32,
                )
                .unwrap_or_else(|| panic!("{authored:?} is unmapped in {statement}"));
                assert_eq!(
                    &document.content[generated_start as usize..generated_end as usize],
                    authored,
                    "{statement}"
                );
                assert!(
                    generated_start as usize > setup,
                    "{authored:?} maps before setup in {statement}"
                );
            }
        }
    }
}
